def merge():
    with open(MAIN, encoding='utf-8') as f:
        main = json.load(f)
    idx = {e['char']: e for e in main['byakuzhi']}
    added = updated = 0
    for e in NEW:
        c = e['char']
        if c not in idx:
            main['byakuzhi'].append(e)
            idx[c] = e
            added += 1
        else:
            ex = idx[c]
            for k in ('readings', 'readings_native', 'readings_sino'):
                merged = list(dict.fromkeys(ex.get(k, []) + e.get(k, [])))
                if merged != ex.get(k, []):
                    ex[k] = merged
                    updated += 1
            if not ex.get('cat') and e.get('cat'):
                ex['cat'] = e['cat']
    main['meta']['version'] = '1.9'
    with open(MAIN, 'w', encoding='utf-8') as f:
        json.dump(main, f, ensure_ascii=False, indent=2)
    print(f'added={added} updated={updated} total={len(main["byakuzhi"])}')

if __name__ == '__main__':
    merge()
